const CACHE = 'delta-sg-__APP_VERSION__-__BUILD_ID__';
const ASSETS = ['./', './index.html', './styles.css', './app.js','./motion.js','./motion-controller.js','./readings.js', './engine.js', './diagnostics.js', './upload.js', './diagnostics-format.js', './version.js', './version.json', './data/roads.json', './data/local-roads.json.gz', './manifest.webmanifest', './icons/icon-192.png', './icons/icon-512.png'];

